# Check if a number is prime
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

num = 17
print(f"{num} is prime: {is_prime(num)}")

class Student:
    def __init__(self, name, grade):
        self.name = name
        self.grade = grade

    def describe(self):
        return f"{self.name} is in grade {self.grade}"

s = Student("Aisha", 10)
print(s.describe())

